#include <iostream>
#include <cstdio>
#include <cstring>
#include <queue>
#include <vector>
#include <climits>
using namespace std;

using T = long long;
const int MAXN = 100010;
const int MAXM = 2000020;
const T INF = 1000000000LL;

struct Edge {
    int next, to, cap;
    T cost;
} edges[MAXM];

int head[MAXN], edge_count = 1, total_nodes;
vector<int> adj_list[MAXN];

void connect(int u, int v, int cap, T cost) {
    edges[++edge_count] = {head[u], v, cap, cost};
    head[u] = edge_count;
    edges[++edge_count] = {head[v], u, 0, -cost};
    head[v] = edge_count;
}

namespace MinCostMaxFlow {
    int current_head[MAXN];
    bool visited[MAXN];
    T distance[MAXN], potential[MAXN];

    struct PQNode {
        int id;
        T priority;
        PQNode(int i = 0, T p = 0) : id(i), priority(p) {}
        bool operator<(const PQNode& other) const {
            return priority > other.priority;
        }
    };

    priority_queue<PQNode> pq;

    bool shortest_path(int src, int dst) {
        fill(distance + 1, distance + total_nodes + 1, INF);
        fill(current_head + 1, current_head + total_nodes + 1, head[1]);
        distance[dst] = 0;
        pq.push(PQNode(dst, 0));

        while (!pq.empty()) {
            int u = pq.top().id;
            pq.pop();
            if (visited[u]) continue;
            visited[u] = true;

            for (int i = head[u]; i; i = edges[i].next) {
                int v = edges[i].to;
                T w = potential[u] + edges[i ^ 1].cost - potential[v];
                if (edges[i ^ 1].cap && distance[u] + w < distance[v]) {
                    distance[v] = distance[u] + w;
                    pq.push(PQNode(v, distance[v]));
                }
            }
        }

        for (int i = 1; i <= total_nodes; ++i)
            potential[i] = min(potential[i] + distance[i], INF);

        if (!visited[src]) return false;
        fill(visited + 1, visited + total_nodes + 1, false);
        return true;
    }

    int augment(int u, int dst, int flow) {
        if (u == dst || !flow) return flow;
        int pushed = 0;
        visited[u] = true;

        for (int& i = current_head[u]; i; i = edges[i].next) {
            if (edges[i].cap) {
                int v = edges[i].to;
                int f;
                if (!visited[v] && potential[v] + edges[i].cost == potential[u] &&
                    (f = augment(v, dst, min(flow, edges[i].cap)))) {
                    edges[i].cap -= f;
                    edges[i ^ 1].cap += f;
                    pushed += f;
                    flow -= f;
                    if (!flow) break;
                }
            }
        }

        visited[u] = false;
        return pushed;
    }

    int max_flow;
    T min_cost;

    void process(int src, int dst) {
        while (shortest_path(src, dst)) {
            int f = augment(src, dst, INF);
            max_flow += f;
            min_cost += (T)f * potential[src];
        }
    }
}

int source_node = 1, sink_node = 2, n, m, k, c, d;

inline int get_node(int t, int x) { return t * n + x + 2; }

void build(int t) {
    total_nodes += n;

    for (int u = 1; u <= n; ++u) {
        for (int v : adj_list[u]) {
            for (int p = 1; p <= k; ++p) {
                connect(get_node(t, u), get_node(t + 1, v), 1, d * (2 * p - 1));
            }
        }
    }

    for (int u = 1; u <= n; ++u) {
        connect(get_node(t, u), get_node(t + 1, u), INF, 0);
    }

    connect(get_node(t + 1, 1), sink_node, INF, c * (t + 1));
}

int main() {
    scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
    total_nodes = n + 2;

    for (int i = 1; i <= k; ++i) {
        int a;
        scanf("%d", &a);
        connect(source_node, get_node(0, a), 1, 0);
    }

    for (int i = 1; i <= m; ++i) {
        int u, v;
        scanf("%d%d", &u, &v);
        adj_list[u].push_back(v);
        adj_list[v].push_back(u);
    }

    connect(get_node(0, 1), sink_node, INF, 0);

    for (int i = 0; i <= n + k; ++i) {
        build(i);
    }

    MinCostMaxFlow::process(source_node, sink_node);
    printf("%lld\n", MinCostMaxFlow::min_cost);
    return 0;
}
